<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian</title>
<meta name="description" content="Piet Mondrian's Composition with Red, Blue and Yellow (1930): De Stijl, Neoplasticism, and why it matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;800&family=Space+Mono:wght@400;700&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#e3302e;
    --blue:#1f4fd8;
    --yellow:#f5c518;
    --black:#111111;
    --white:#f7f5ef;
    --grey:#d8d4c9;
    --ink:#16130f;
    --max:1100px;
    --line:6px;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html{scroll-behavior:smooth}
  body{
    font-family:'Archivo',system-ui,sans-serif;
    background:var(--white);
    color:var(--ink);
    line-height:1.6;
    -webkit-font-smoothing:antialiased;
  }
  ::selection{background:var(--yellow);color:var(--black)}
  .mono{font-family:'Space Mono',monospace}

  .frame{
    min-height:100vh;
    display:flex;
    flex-direction:column;
    border-bottom:var(--line) solid var(--black);
  }

  /* ---------- header ---------- */
  header{
    display:flex;align-items:center;justify-content:space-between;
    padding:1.1rem clamp(1.25rem,4vw,2.5rem);
    border-bottom:var(--line) solid var(--black);
    background:var(--white);
  }
  .brand{display:flex;align-items:center;gap:.7rem;text-decoration:none;color:var(--ink)}
  .brand-mark{display:grid;grid-template-columns:repeat(2,12px);grid-template-rows:repeat(2,12px);gap:2px;border:2px solid var(--black)}
  .brand-mark span{border:1px solid var(--black)}
  .brand-mark span:nth-child(1){background:var(--white)}
  .brand-mark span:nth-child(2){background:var(--red)}
  .brand-mark span:nth-child(3){background:var(--yellow)}
  .brand-mark span:nth-child(4){background:var(--blue)}
  .brand strong{font-weight:800;letter-spacing:.04em;font-size:.9rem;text-transform:uppercase}
  .tag{font-size:.72rem;letter-spacing:.14em;text-transform:uppercase}

  /* ---------- hero ---------- */
  .hero{
    flex:1;
    display:grid;
    grid-template-columns:1.05fr .95fr;
    gap:clamp(1.5rem,4vw,3rem);
    align-items:center;
    padding:clamp(1.5rem,4vw,3rem) clamp(1.25rem,4vw,2.5rem);
    max-width:var(--max);
    width:100%;
    margin:0 auto;
  }
  .kicker{
    display:inline-flex;align-items:center;gap:.6rem;
    font-family:'Space Mono',monospace;font-size:.72rem;letter-spacing:.22em;text-transform:uppercase;
    border:2px solid var(--black);padding:.35rem .8rem;margin-bottom:1.4rem;background:var(--white);
  }
  .kicker i{width:.6rem;height:.6rem;background:var(--red);display:inline-block}
  h1{
    font-weight:800;
    font-size:clamp(2.4rem,6vw,4.4rem);
    line-height:.98;
    letter-spacing:-.02em;
    text-transform:uppercase;
    margin-bottom:1.2rem;
  }
  h1 .accent{color:var(--blue)}
  .lede{font-size:1.12rem;max-width:46ch;margin-bottom:1.6rem}
  .hero-meta{display:flex;flex-wrap:wrap;gap:.75rem}
  .chip{
    font-family:'Space Mono',monospace;font-size:.78rem;letter-spacing:.06em;
    border:2px solid var(--black);padding:.45rem .8rem;background:#fff;
  }
  .chip b{color:var(--blue)}

  /* ---------- composition artwork ---------- */
  .art-wrap{position:relative}
  .art{
    display:grid;
    grid-template-columns:1.05fr 1.25fr;
    grid-template-rows:1.15fr 1fr 1fr;
    gap:var(--line);
    background:var(--black);
    border:var(--line) solid var(--black);
    aspect-ratio:4/5;
    box-shadow:14px 14px 0 var(--black);
  }
